from __future__ import annotations

import json
from pathlib import Path

import pytest
from jsonschema import Draft202012Validator, ValidationError, validate

from trace_to_golden.dedupe import find_duplicates, normalize
from trace_to_golden.export.regression_detector import (
    DatasetSchema,
    ExportResult,
    case_id,
    export_candidates,
    load_existing_inputs,
    to_v1_case,
    to_v2_case,
    write_dataset,
)
from trace_to_golden.models import Flag, GoldenCandidate, ReviewStatus

# Copy of llm-regression-detector/schemas/golden-dataset.v2.schema.json (generated by
# `uv run lrd schema` there), so this repo's CI checks exports without the sibling repo.
V2_SCHEMA = json.loads(
    (Path(__file__).parent / "fixtures" / "golden-dataset.v2.schema.json").read_text(
        encoding="utf-8"
    )
)

# Field set of GoldenCase (schema v1) in llm-regression-detector, extra="forbid".
GOLDEN_CASE_V1_FIELDS = {
    "id",
    "topic",
    "input_text",
    "expected_category",
    "expected_summary_keywords",
    "difficulty",
    "notes",
}


def approved_candidate(
    record_id: str,
    text: str,
    category: str | None = "returns",
    reference_answer: str = "Within 30 days from the Orders page.",
    rubric: tuple[str, ...] | None = None,
) -> GoldenCandidate:
    return GoldenCandidate(
        record_id=record_id,
        status=ReviewStatus.APPROVED,
        input_text=text,
        reference_answer=reference_answer,
        category=category,
        rubric=rubric,
        topic="return, item",
        flags=(Flag.NEGATIVE_FEEDBACK,),
    )


def test_normalize_drops_placeholders_case_and_punctuation():
    assert normalize("  How do I RETURN   an item?! ") == "how do i return an item"
    assert normalize("Hi, I'm <PERSON>. Refund?") == "hi i m refund"
    assert normalize("Où en est ma commande ?") == "où en est ma commande"


def test_find_duplicates_against_existing_cases_and_earlier_candidates():
    assert find_duplicates([], ["x"], threshold=0.9) == []
    reasons = find_duplicates(
        [
            "how do i return an item",
            "How do I return an item?",
            "Où en est ma commande ?",
            "Où en est ma commande?",
            "Is the tent in stock?",
        ],
        ["How do I RETURN an item"],
        threshold=0.9,
    )
    assert reasons[0] == "exact duplicate of existing case"
    assert reasons[1] == "exact duplicate of existing case"
    assert reasons[2] is None
    assert reasons[3] == "exact duplicate of earlier candidate"
    assert reasons[4] is None


def test_near_duplicate_threshold():
    texts = ["where is my order right now", "where is my order now"]
    [_, near] = find_duplicates(texts, [], threshold=0.5)
    assert near is not None
    assert near.startswith("near (")
    assert find_duplicates(texts, [], threshold=0.99) == [None, None]


def test_v1_case_matches_golden_case_fields():
    case = to_v1_case(approved_candidate("t1:s1", "How do I return an item?"))
    assert set(case) <= GOLDEN_CASE_V1_FIELDS
    assert case["id"] == case_id("t1:s1")
    assert case["id"].startswith("ttg-")
    assert case["expected_category"] == "returns"
    assert "negative_feedback" in case["notes"]
    no_topic = to_v1_case(
        approved_candidate("t1:s2", "Q?").model_copy(update={"topic": None, "flags": ()})
    )
    assert "topic" not in no_topic
    assert no_topic["notes"].endswith("flags: none")


def test_v2_case_omits_empty_fields():
    case = to_v2_case(
        approved_candidate("t1:s1", "How do I return an item?", rubric=("Says 30 days.",))
    )
    assert case == {
        "id": case_id("t1:s1"),
        "topic": "return, item",
        "input_text": "How do I return an item?",
        "expected_category": "returns",
        "reference_answer": "Within 30 days from the Orders page.",
        "rubric": ["Says 30 days."],
        "source": {"origin": "trace-to-golden", "trace": "t1:s1", "flags": "negative_feedback"},
    }
    bare = to_v2_case(approved_candidate("t1:s2", "Q?", category=None, reference_answer="  "))
    assert "reference_answer" not in bare
    assert "rubric" not in bare
    assert "expected_category" not in bare


def test_v1_export_skips_unapproved_uncategorized_and_duplicates():
    pending = GoldenCandidate(record_id="p:1", input_text="Pending?", reference_answer="x")
    result = export_candidates(
        [
            approved_candidate("a:1", "How do I return an item?"),
            approved_candidate("a:2", "When will I get my refund?", category=None),
            approved_candidate("a:3", "Comment retourner un article ?"),
            pending,
        ],
        existing_inputs=["Comment retourner un article ?"],
        dedupe_similarity_threshold=0.9,
        schema=DatasetSchema.V1,
    )
    assert [c["input_text"] for c in result.cases] == ["How do I return an item?"]
    assert result.skipped == {
        "a:2": "schema v1 needs a category",
        "a:3": "exact duplicate of existing case",
    }


def test_v2_export_needs_something_to_score():
    result = export_candidates(
        [
            approved_candidate("a:1", "When will I get my refund?", category=None),
            approved_candidate(
                "a:2", "Is the tent in stock?", category=None, rubric=("Names the size.",)
            ),
            approved_candidate("a:3", "Hello?", category=None, reference_answer=""),
        ],
        existing_inputs=[],
        dedupe_similarity_threshold=0.9,
    )
    assert result.schema is DatasetSchema.V2
    assert [c["input_text"] for c in result.cases] == [
        "When will I get my refund?",
        "Is the tent in stock?",
    ]
    assert result.skipped == {"a:3": "schema v2 needs a category, a reference answer or a rubric"}


def test_v2_file_matches_regression_detector_schema(tmp_path: Path):
    Draft202012Validator.check_schema(V2_SCHEMA)
    result = export_candidates(
        [
            approved_candidate(
                "a:1", "How do I return an item?", rubric=("Says 30 days.", "Links Orders.")
            ),
            approved_candidate("a:2", "Où est ma commande ?", category=None),
        ],
        existing_inputs=[],
        dedupe_similarity_threshold=0.9,
    )
    path = tmp_path / "golden.json"
    write_dataset(result, path)
    document = json.loads(path.read_text(encoding="utf-8"))
    validate(document, V2_SCHEMA, cls=Draft202012Validator)
    assert document["schema_version"] == 2
    assert load_existing_inputs(path) == ["How do I return an item?", "Où est ma commande ?"]
    with pytest.raises(ValidationError):
        validate({"schema_version": 2, "cases": []}, V2_SCHEMA, cls=Draft202012Validator)


def test_v1_write_and_load(tmp_path: Path):
    path = tmp_path / "nested" / "golden.json"
    case = to_v1_case(approved_candidate("a:1", "Où est ma commande ?"))
    write_dataset(ExportResult(schema=DatasetSchema.V1, cases=[case]), path)
    assert json.loads(path.read_text(encoding="utf-8"))[0]["input_text"] == "Où est ma commande ?"
    path.write_text(json.dumps([{"input_text": "A"}, {"id": "no input"}]), encoding="utf-8")
    assert load_existing_inputs(path) == ["A"]
